import { MogsAIProject, MinecraftPlatform, BuildTool } from '../types/mogsai';

export function createFabricItemMod(version: string = '1.21.1'): MogsAIProject {
  const javaVersion = 21;
  const modId = 'mogsitems';
  const modName = 'Mogs Custom Items';
  const packageName = 'com.mogsai.fabricmod';

  const fabricModJson = `{
  "schemaVersion": 1,
  "id": "${modId}",
  "version": "1.0.0",
  "name": "${modName}",
  "description": "Autonomous Fabric 1.21 Mod generated by MogsAI",
  "authors": ["MogsAI"],
  "license": "MIT",
  "environment": "*",
  "entrypoints": {
    "main": [
      "${packageName}.MogsFabricMod"
    ]
  },
  "depends": {
    "fabricloader": ">=0.16.0",
    "minecraft": "~${version}",
    "java": ">=21",
    "fabric-api": "*"
  }
}
`;

  const buildGradle = `plugins {
    id 'fabric-loom' version '1.7-SNAPSHOT'
    id 'maven-publish'
}

version = '1.0.0'
group = '${packageName}'

base {
    archivesName = '${modId}'
}

java {
    toolchain.languageVersion = JavaLanguageVersion.of(${javaVersion})
}

dependencies {
    minecraft "com.mojang:minecraft:${version}"
    mappings "net.fabricmc:yarn:${version}+build.1:v2"
    modImplementation "net.fabricmc:fabric-loader:0.16.5"
    modImplementation "net.fabricmc.fabric-api:fabric-api:0.100.8+${version}"
}

processResources {
    inputs.property "version", project.version
    filteringCharset "UTF-8"
    filesMatching("fabric.mod.json") {
        expand "version": project.version
    }
}
`;

  const mainJava = `package ${packageName};

import net.fabricmc.api.ModInitializer;
import net.fabricmc.fabric.api.itemgroup.v1.ItemGroupEvents;
import net.minecraft.item.Item;
import net.minecraft.item.ItemGroups;
import net.minecraft.registry.Registries;
import net.minecraft.registry.Registry;
import net.minecraft.util.Identifier;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class MogsFabricMod implements ModInitializer {
    public static final String MOD_ID = "${modId}";
    public static final Logger LOGGER = LoggerFactory.getLogger(MOD_ID);

    // Custom Item
    public static final Item RUBY_BLADE = Registry.register(
            Registries.ITEM,
            Identifier.of(MOD_ID, "ruby_blade"),
            new Item(new Item.Settings().maxCount(1).fireproof())
    );

    @Override
    public void onInitialize() {
        LOGGER.info("Initializing MogsCustomItems on Fabric 1.21!");

        // Add to Combat Item Group
        ItemGroupEvents.modifyEntriesEvent(ItemGroups.COMBAT).register(entries -> {
            entries.add(RUBY_BLADE);
        });
    }
}
`;

  return {
    id: 'proj_fabric_121',
    name: modName,
    description: 'Autonomous Fabric 1.21.x Item Mod with modern Fabric API registration.',
    platform: 'fabric',
    version,
    javaVersion,
    buildTool: 'gradle',
    currentMode: 'generate',
    createdAt: new Date().toISOString(),
    files: [
      { path: 'build.gradle', content: buildGradle, language: 'groovy' },
      { path: 'src/main/resources/fabric.mod.json', content: fabricModJson, language: 'json' },
      { path: `src/main/java/${packageName.replace(/\./g, '/')}/MogsFabricMod.java`, content: mainJava, language: 'java' },
      {
        path: 'README.md',
        content: `# ${modName}\n\nFabric 1.21.x mod created with MogsAI.\n\n### Build\nRun \`./gradlew build\` to generate the mod jar in \`build/libs/\`.`,
        language: 'markdown',
      },
    ],
    projectMap: {
      entryPoint: `${packageName}.MogsFabricMod`,
      commands: [],
      permissions: [],
      listeners: [{ name: 'ItemGroupEvents', events: ['modifyEntriesEvent'], description: 'Registers ruby blade to Combat tab' }],
      managers: [{ name: 'Registries.ITEM', responsibility: 'Fabric vanilla item registry' }],
      storage: { type: 'Minecraft Data Components', details: 'Uses 1.21 component item settings' },
      integrations: ['Fabric API 0.100.8', 'Fabric Loader 0.16.5'],
      architectureOverview: 'Fabric ModInitializer lifecycle registering custom items into Registries.ITEM.',
    },
    validationChecks: [
      { name: 'fabric.mod.json schema', status: 'passed', message: 'Schema v1 compliant with valid entrypoints.' },
      { name: 'Java 21 Toolchain', status: 'passed', message: 'Fabric 1.21 requires Java 21.' },
    ],
    debugHistory: [],
    reviewIssues: [],
    readme: '# Fabric Mod\nBuilt with MogsAI',
  };
}

export function createSkriptKitProject(): MogsAIProject {
  const skriptCode = `# ========================================================
# MogsKits - Advanced Autonomous Skript Script
# Target: Skript 2.9.x for Paper 1.21
# ========================================================

options:
    prefix: <#00f2fe>[MogsKits]<reset>
    pvp_cooldown: 3600 seconds
    archer_cooldown: 1800 seconds

# Command /kit
command /kit [<text>]:
    description: Open the Kit GUI or claim a kit directly
    permission: mogskits.use
    permission message: {@prefix} <red>You do not have permission to use kits!</red>
    trigger:
        if arg-1 is not set:
            openKitGui(player)
            stop

        if arg-1 is "pvp":
            claimKit(player, "pvp", "Warrior Kit", {@pvp_cooldown}, diamond sword named "<red>Warrior Blade</red>", 32 cooked beef)
        else if arg-1 is "archer":
            claimKit(player, "archer", "Archer Kit", {@archer_cooldown}, bow named "<aqua>Ranger Bow</aqua>", 64 arrow)
        else:
            send "{@prefix} <red>Unknown kit: %arg-1%</red>" to player

# Function to Open Modern Chest GUI
function openKitGui(p: player):
    create a gui with virtual chest inventory with 3 rows named "<bold><#00f2fe>Select a Kit</bold>":
        # Background fillers
        format gui slot (integers between 0 and 26) with gray stained glass pane named "&7"
        
        # Warrior Kit Slot 11
        format gui slot 11 with diamond sword named "<red><bold>Warrior Kit</bold></red>" with lore "&7Click to claim your combat gear!":
            close player's inventory
            execute player command "/kit pvp"

        # Archer Kit Slot 15
        format gui slot 15 with bow named "<aqua><bold>Archer Kit</bold></aqua>" with lore "&7Click to claim your ranger gear!":
            close player's inventory
            execute player command "/kit archer"
    open the last gui for {_p}

# Reusable Function to Claim Kits with Cooldowns
function claimKit(p: player, kitId: text, kitName: text, cd: timespan, items: items):
    set {_now} to now
    set {_lastClaim} to {kit::%{_kitId}%::%{_p}'s uuid%}

    if {_lastClaim} is set:
        set {_waited} to difference between {_lastClaim} and {_now}
        if {_waited} < {_cd}:
            set {_rem} to difference between {_cd} and {_waited}
            send "{@prefix} <yellow>You must wait <gold>%{_rem}%</gold> before claiming this kit again!</yellow>" to {_p}
            play sound "entity.villager.no" at {_p}
            stop

    # Give Items
    give {_items} to {_p}
    set {kit::%{_kitId}%::%{_p}'s uuid%} to {_now}
    send "{@prefix} <green>You claimed the <aqua>%{_kitName}%</aqua>!</green>" to {_p}
    play sound "entity.player.levelup" at {_p}
`;

  return {
    id: 'proj_skript_kits',
    name: 'MogsKits Skript',
    description: 'High-performance Skript script with GUI, cooldown variables, and sound effects.',
    platform: 'skript',
    version: '1.21.1',
    javaVersion: 21,
    buildTool: 'none',
    currentMode: 'generate',
    createdAt: new Date().toISOString(),
    files: [
      { path: 'plugins/Skript/scripts/kits.sk', content: skriptCode, language: 'skript' },
      {
        path: 'README.md',
        content: `# MogsKits Skript\nDrop \`kits.sk\` into \`plugins/Skript/scripts/\` and reload with \`/sk reload kits\`.`,
        language: 'markdown',
      },
    ],
    projectMap: {
      entryPoint: 'plugins/Skript/scripts/kits.sk',
      commands: [{ name: 'kit', permission: 'mogskits.use', description: 'Opens GUI or claims kit', usage: '/kit [name]' }],
      permissions: [{ node: 'mogskits.use', description: 'Use kit system', default: 'true' }],
      listeners: [],
      managers: [{ name: 'openKitGui function', responsibility: 'Constructs chest GUI' }, { name: 'claimKit function', responsibility: 'Validates cooldown and distributes items' }],
      storage: { type: 'Skript Variables {kit::*}', details: 'Persistent server variables' },
      integrations: ['Skript 2.9+'],
      architectureOverview: 'Event & Function based Skript script with virtual inventory GUI formatting.',
    },
    validationChecks: [
      { name: 'Skript Syntax & Indentation', status: 'passed', message: 'Valid 4-space tab indentation and trigger blocks.' },
      { name: 'GUI Virtual Inventory Format', status: 'passed', message: 'Modern virtual chest inventory syntax compliant.' },
    ],
    debugHistory: [],
    reviewIssues: [],
    readme: '# Skript Kit System\nReady for Skript 2.9 on Paper 1.21',
  };
}

