  const mainPluginJava = `package ${packageName};

import ${packageName}.command.KitCommand;
import ${packageName}.command.KitAdminCommand;
import ${packageName}.listener.KitGuiListener;
import ${packageName}.manager.CooldownManager;
import ${packageName}.manager.KitManager;
import ${packageName}.storage.PlayerDataStorage;
import ${packageName}.util.MessageUtil;
import org.bukkit.plugin.java.JavaPlugin;

import java.io.File;

/**
 * MogsKits - Production-grade Paper 1.21 Kit Plugin
 * Built autonomously with MogsAI Architecture Engine.
 */
public final class KitPlugin extends JavaPlugin {

    private static KitPlugin instance;
    private KitManager kitManager;
    private CooldownManager cooldownManager;
    private PlayerDataStorage dataStorage;

    @Override
    public void onEnable() {
        instance = this;

        // 1. Initialize configuration
        saveDefaultConfig();

        // 2. Initialize Storage & Managers
        File dataFolder = new File(getDataFolder(), "playerdata");
        if (!dataFolder.exists()) {
            dataFolder.mkdirs();
        }
        this.dataStorage = new PlayerDataStorage(this, dataFolder);
        this.cooldownManager = new CooldownManager(this, dataStorage);
        this.kitManager = new KitManager(this);
        this.kitManager.loadKits();

        // 3. Register Events
        getServer().getPluginManager().registerEvents(new KitGuiListener(this), this);

        // 4. Register Commands
        if (getCommand("kit") != null) {
            getCommand("kit").setExecutor(new KitCommand(this));
            getCommand("kit").setTabCompleter(new KitCommand(this));
        }
        if (getCommand("kitadmin") != null) {
            getCommand("kitadmin").setExecutor(new KitAdminCommand(this));
            getCommand("kitadmin").setTabCompleter(new KitAdminCommand(this));
        }

        getLogger().info("MogsKits has been successfully enabled on Paper 1.21!");
    }

    @Override
    public void onDisable() {
        if (dataStorage != null) {
            dataStorage.saveAllSync();
        }
        getLogger().info("MogsKits has been safely disabled. Player data saved.");
    }

    public void reloadPlugin() {
        reloadConfig();
        kitManager.loadKits();
        getLogger().info("Configuration reloaded.");
    }

    public static KitPlugin getInstance() {
        return instance;
    }

    public KitManager getKitManager() {
        return kitManager;
    }

    public CooldownManager getCooldownManager() {
        return cooldownManager;
    }

    public PlayerDataStorage getDataStorage() {
        return dataStorage;
    }
}
`;

  const kitModelJava = `package ${packageName}.model;

import net.kyori.adventure.text.Component;
import org.bukkit.Material;
import org.bukkit.inventory.ItemStack;

import java.util.List;

public class Kit {
    private final String id;
    private final Component displayName;
    private final Material icon;
    private final int slot;
    private final String permission;
    private final long cooldownSeconds;
    private final List<Component> description;
    private final List<ItemStack> items;

    public Kit(String id, Component displayName, Material icon, int slot, String permission,
               long cooldownSeconds, List<Component> description, List<ItemStack> items) {
        this.id = id;
        this.displayName = displayName;
        this.icon = icon;
        this.slot = slot;
        this.permission = permission;
        this.cooldownSeconds = cooldownSeconds;
        this.description = description;
        this.items = items;
    }

    public String getId() {
        return id;
    }

    public Component getDisplayName() {
        return displayName;
    }

    public Material getIcon() {
        return icon;
    }

    public int getSlot() {
        return slot;
    }

    public String getPermission() {
        return permission;
    }

    public long getCooldownSeconds() {
        return cooldownSeconds;
    }

    public List<Component> getDescription() {
        return description;
    }

    public List<ItemStack> getItems() {
        return items;
    }
}
`;

  const kitManagerJava = `package ${packageName}.manager;

import ${packageName}.KitPlugin;
import ${packageName}.model.Kit;
import ${packageName}.util.MessageUtil;
import net.kyori.adventure.text.Component;
import org.bukkit.Material;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.enchantments.Enchantment;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;

import java.util.*;

public class KitManager {

    private final KitPlugin plugin;
    private final Map<String, Kit> kits = new LinkedHashMap<>();

    public KitManager(KitPlugin plugin) {
        this.plugin = plugin;
    }

    public void loadKits() {
        kits.clear();
        ConfigurationSection section = plugin.getConfig().getConfigurationSection("kits");
        if (section == null) return;

        for (String key : section.getKeys(false)) {
            ConfigurationSection kitSec = section.getConfigurationSection(key);
            if (kitSec == null) continue;

            String rawName = kitSec.getString("display-name", key);
            Component displayName = MessageUtil.parse(rawName);
            Material icon = Material.matchMaterial(kitSec.getString("icon", "CHEST"));
            if (icon == null) icon = Material.CHEST;
            int slot = kitSec.getInt("slot", 10);
            String permission = kitSec.getString("permission", "mogskits.kit." + key);
            long cooldown = kitSec.getLong("cooldown-seconds", 3600);

            List<Component> lore = new ArrayList<>();
            for (String line : kitSec.getStringList("description")) {
                lore.add(MessageUtil.parse(line));
            }

            List<ItemStack> items = new ArrayList<>();
            List<Map<?, ?>> itemMaps = kitSec.getMapList("items");
            for (Map<?, ?> itemMap : itemMaps) {
                String matStr = String.valueOf(itemMap.get("material"));
                Material mat = Material.matchMaterial(matStr);
                if (mat == null) mat = Material.DIRT;

                int amount = 1;
                if (itemMap.containsKey("amount")) {
                    amount = ((Number) itemMap.get("amount")).intValue();
                }

                ItemStack stack = new ItemStack(mat, amount);
                ItemMeta meta = stack.getItemMeta();
                if (meta != null) {
                    if (itemMap.containsKey("name")) {
                        meta.displayName(MessageUtil.parse(String.valueOf(itemMap.get("name"))));
                    }
                    if (itemMap.containsKey("enchantments") && itemMap.get("enchantments") instanceof Map<?, ?> encMap) {
                        for (Map.Entry<?, ?> entry : encMap.entrySet()) {
                            try {
                                Enchantment enc = Enchantment.getByName(String.valueOf(entry.getKey()).toUpperCase());
                                if (enc != null) {
                                    meta.addEnchant(enc, ((Number) entry.getValue()).intValue(), true);
                                }
                            } catch (Exception ignored) {}
                        }
                    }
                    stack.setItemMeta(meta);
                }
                items.add(stack);
            }

            Kit kit = new Kit(key, displayName, icon, slot, permission, cooldown, lore, items);
            kits.put(key.toLowerCase(), kit);
        }
        plugin.getLogger().info("Loaded " + kits.size() + " kit(s).");
    }

    public Optional<Kit> getKit(String id) {
        return Optional.ofNullable(kits.get(id.toLowerCase()));
    }

    public Collection<Kit> getAllKits() {
        return Collections.unmodifiableCollection(kits.values());
    }

    public boolean giveKit(Player player, Kit kit) {
        for (ItemStack item : kit.getItems()) {
            HashMap<Integer, ItemStack> leftover = player.getInventory().addItem(item.clone());
            if (!leftover.isEmpty()) {
                for (ItemStack drop : leftover.values()) {
                    player.getWorld().dropItemNaturally(player.getLocation(), drop);
                }
                player.sendMessage(MessageUtil.parse(plugin.getConfig().getString("messages.inventory-full")));
            }
        }
        return true;
    }
}
`;

  const cooldownManagerJava = `package ${packageName}.manager;

import ${packageName}.KitPlugin;
import ${packageName}.model.Kit;
import ${packageName}.storage.PlayerDataStorage;
import org.bukkit.entity.Player;

import java.util.UUID;

public class CooldownManager {

    private final KitPlugin plugin;
    private final PlayerDataStorage storage;

    public CooldownManager(KitPlugin plugin, PlayerDataStorage storage) {
        this.plugin = plugin;
        this.storage = storage;
    }

    public boolean isOnCooldown(Player player, Kit kit) {
        if (player.hasPermission("mogskits.bypass.cooldown") || player.hasPermission("mogskits.admin")) {
            return false;
        }

        long lastClaim = storage.getLastClaimTime(player.getUniqueId(), kit.getId());
        long now = System.currentTimeMillis();
        long diffSeconds = (now - lastClaim) / 1000;

        return diffSeconds < kit.getCooldownSeconds();
    }

    public long getRemainingSeconds(Player player, Kit kit) {
        long lastClaim = storage.getLastClaimTime(player.getUniqueId(), kit.getId());
        long now = System.currentTimeMillis();
        long diffSeconds = (now - lastClaim) / 1000;
        long remaining = kit.getCooldownSeconds() - diffSeconds;
        return Math.max(0, remaining);
    }

    public void setClaimed(Player player, Kit kit) {
        storage.setLastClaimTime(player.getUniqueId(), kit.getId(), System.currentTimeMillis());
    }

    public void resetCooldown(UUID uuid, String kitId) {
        storage.setLastClaimTime(uuid, kitId, 0);
    }

    public String formatRemaining(long seconds) {
        if (seconds < 60) return seconds + "s";
        long minutes = seconds / 60;
        long hours = minutes / 60;
        if (hours > 0) {
            return hours + "h " + (minutes % 60) + "m";
        }
        return minutes + "m " + (seconds % 60) + "s";
    }
}
`;

