  const kitGuiJava = `package ${packageName}.gui;

import ${packageName}.KitPlugin;
import ${packageName}.model.Kit;
import ${packageName}.util.MessageUtil;
import net.kyori.adventure.text.Component;
import org.bukkit.Bukkit;
import org.bukkit.Material;
import org.bukkit.NamespacedKey;
import org.bukkit.entity.Player;
import org.bukkit.inventory.Inventory;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.persistence.PersistentDataType;

import java.util.ArrayList;
import java.util.List;

public class KitGui {

    public static final NamespacedKey KIT_KEY = new NamespacedKey(KitPlugin.getInstance(), "gui_kit_id");

    public static void open(Player player) {
        KitPlugin plugin = KitPlugin.getInstance();
        KitGuiHolder holder = new KitGuiHolder();
        Component title = MessageUtil.parse("<gradient:#00f2fe:#4facfe><bold>Select a Kit</bold></gradient>");
        Inventory inv = Bukkit.createInventory(holder, 27, title);
        holder.setInventory(inv);

        // Fill background with dark stained glass
        ItemStack filler = new ItemStack(Material.GRAY_STAINED_GLASS_PANE);
        ItemMeta fillMeta = filler.getItemMeta();
        if (fillMeta != null) {
            fillMeta.displayName(Component.empty());
            filler.setItemMeta(fillMeta);
        }
        for (int i = 0; i < 27; i++) {
            inv.setItem(i, filler);
        }

        // Place kits
        for (Kit kit : plugin.getKitManager().getAllKits()) {
            ItemStack icon = new ItemStack(kit.getIcon());
            ItemMeta meta = icon.getItemMeta();
            if (meta != null) {
                meta.displayName(kit.getDisplayName());
                List<Component> lore = new ArrayList<>(kit.getDescription());
                lore.add(Component.empty());

                boolean hasPerm = player.hasPermission(kit.getPermission());
                boolean onCd = plugin.getCooldownManager().isOnCooldown(player, kit);

                if (!hasPerm) {
                    lore.add(MessageUtil.parse("<red>✖ Locked - No Permission</red>"));
                } else if (onCd) {
                    long remaining = plugin.getCooldownManager().getRemainingSeconds(player, kit);
                    lore.add(MessageUtil.parse("<yellow>⏳ Cooldown: " + plugin.getCooldownManager().formatRemaining(remaining) + "</yellow>"));
                } else {
                    lore.add(MessageUtil.parse("<green>✔ Click to Claim!</green>"));
                }

                meta.lore(lore);
                // Mark with PDC
                meta.getPersistentDataContainer().set(KIT_KEY, PersistentDataType.STRING, kit.getId());
                icon.setItemMeta(meta);
            }
            if (kit.getSlot() >= 0 && kit.getSlot() < 27) {
                inv.setItem(kit.getSlot(), icon);
            }
        }

        player.openInventory(inv);
    }
}
`;

  const kitGuiListenerJava = `package ${packageName}.listener;

import ${packageName}.KitPlugin;
import ${packageName}.gui.KitGui;
import ${packageName}.gui.KitGuiHolder;
import ${packageName}.model.Kit;
import ${packageName}.util.MessageUtil;
import org.bukkit.Sound;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.inventory.InventoryClickEvent;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.persistence.PersistentDataType;

public class KitGuiListener implements Listener {

    private final KitPlugin plugin;

    public KitGuiListener(KitPlugin plugin) {
        this.plugin = plugin;
    }

    @EventHandler
    public void onInventoryClick(InventoryClickEvent event) {
        if (!(event.getInventory().getHolder() instanceof KitGuiHolder)) {
            return;
        }

        // Cancel all clicks in kit GUI to prevent item theft
        event.setCancelled(true);

        if (!(event.getWhoClicked() instanceof Player player)) return;
        ItemStack clicked = event.getCurrentItem();
        if (clicked == null || !clicked.hasItemMeta()) return;

        ItemMeta meta = clicked.getItemMeta();
        if (!meta.getPersistentDataContainer().has(KitGui.KIT_KEY, PersistentDataType.STRING)) {
            return;
        }

        String kitId = meta.getPersistentDataContainer().get(KitGui.KIT_KEY, PersistentDataType.STRING);
        if (kitId == null) return;

        Kit kit = plugin.getKitManager().getKit(kitId).orElse(null);
        if (kit == null) {
            player.sendMessage(MessageUtil.parse(plugin.getConfig().getString("messages.kit-not-found")));
            return;
        }

        if (!player.hasPermission(kit.getPermission())) {
            player.sendMessage(MessageUtil.parse(plugin.getConfig().getString("messages.no-permission")));
            player.playSound(player.getLocation(), Sound.ENTITY_VILLAGER_NO, 1.0f, 1.0f);
            return;
        }

        if (plugin.getCooldownManager().isOnCooldown(player, kit)) {
            long remaining = plugin.getCooldownManager().getRemainingSeconds(player, kit);
            String formatted = plugin.getCooldownManager().formatRemaining(remaining);
            String msg = plugin.getConfig().getString("messages.cooldown-active", "").replace("{time}", formatted);
            player.sendMessage(MessageUtil.parse(msg));
            player.playSound(player.getLocation(), Sound.BLOCK_CHEST_LOCKED, 1.0f, 1.0f);
            return;
        }

        // Claim kit
        plugin.getKitManager().giveKit(player, kit);
        plugin.getCooldownManager().setClaimed(player, kit);

        String msg = plugin.getConfig().getString("messages.kit-claimed", "").replace("{kit}", kit.getId());
        player.sendMessage(MessageUtil.parse(msg));

        if (plugin.getConfig().getBoolean("settings.play-sound-on-claim", true)) {
            player.playSound(player.getLocation(), Sound.ENTITY_PLAYER_LEVELUP, 1.0f, 1.2f);
        }

        if (plugin.getConfig().getBoolean("settings.close-gui-on-claim", true)) {
            player.closeInventory();
        } else {
            KitGui.open(player); // Refresh
        }
    }
}
`;

  const kitCommandJava = `package ${packageName}.command;

import ${packageName}.KitPlugin;
import ${packageName}.gui.KitGui;
import ${packageName}.model.Kit;
import ${packageName}.util.MessageUtil;
import org.bukkit.command.Command;
import org.bukkit.command.CommandExecutor;
import org.bukkit.command.CommandSender;
import org.bukkit.command.TabCompleter;
import org.bukkit.entity.Player;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.ArrayList;
import java.util.List;

public class KitCommand implements CommandExecutor, TabCompleter {

    private final KitPlugin plugin;

    public KitCommand(KitPlugin plugin) {
        this.plugin = plugin;
    }

    @Override
    public boolean onCommand(@NotNull CommandSender sender, @NotNull Command command, @NotNull String label, @NotNull String[] args) {
        if (!(sender instanceof Player player)) {
            sender.sendMessage("This command can only be executed by players.");
            return true;
        }

        if (!player.hasPermission("mogskits.use")) {
            player.sendMessage(MessageUtil.parse(plugin.getConfig().getString("messages.no-permission")));
            return true;
        }

        if (args.length == 0) {
            KitGui.open(player);
            return true;
        }

        String kitName = args[0];
        Kit kit = plugin.getKitManager().getKit(kitName).orElse(null);
        if (kit == null) {
            player.sendMessage(MessageUtil.parse(plugin.getConfig().getString("messages.kit-not-found")));
            return true;
        }

        if (!player.hasPermission(kit.getPermission())) {
            player.sendMessage(MessageUtil.parse(plugin.getConfig().getString("messages.no-permission")));
            return true;
        }

        if (plugin.getCooldownManager().isOnCooldown(player, kit)) {
            long remaining = plugin.getCooldownManager().getRemainingSeconds(player, kit);
            String formatted = plugin.getCooldownManager().formatRemaining(remaining);
            String msg = plugin.getConfig().getString("messages.cooldown-active", "").replace("{time}", formatted);
            player.sendMessage(MessageUtil.parse(msg));
            return true;
        }

        plugin.getKitManager().giveKit(player, kit);
        plugin.getCooldownManager().setClaimed(player, kit);

        String msg = plugin.getConfig().getString("messages.kit-claimed", "").replace("{kit}", kit.getId());
        player.sendMessage(MessageUtil.parse(msg));
        return true;
    }

    @Override
    public @Nullable List<String> onTabComplete(@NotNull CommandSender sender, @NotNull Command command, @NotNull String label, @NotNull String[] args) {
        List<String> completions = new ArrayList<>();
        if (args.length == 1) {
            for (Kit kit : plugin.getKitManager().getAllKits()) {
                if (sender.hasPermission(kit.getPermission()) && kit.getId().toLowerCase().startsWith(args[0].toLowerCase())) {
                    completions.add(kit.getId());
                }
            }
        }
        return completions;
    }
}
`;

  const kitAdminCommandJava = `package ${packageName}.command;

import ${packageName}.KitPlugin;
import ${packageName}.util.MessageUtil;
import org.bukkit.Bukkit;
import org.bukkit.OfflinePlayer;
import org.bukkit.command.Command;
import org.bukkit.command.CommandExecutor;
import org.bukkit.command.CommandSender;
import org.bukkit.command.TabCompleter;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class KitAdminCommand implements CommandExecutor, TabCompleter {

    private final KitPlugin plugin;

    public KitAdminCommand(KitPlugin plugin) {
        this.plugin = plugin;
    }

    @Override
    public boolean onCommand(@NotNull CommandSender sender, @NotNull Command command, @NotNull String label, @NotNull String[] args) {
        if (!sender.hasPermission("mogskits.admin")) {
            sender.sendMessage(MessageUtil.parse(plugin.getConfig().getString("messages.no-permission")));
            return true;
        }

        if (args.length == 0) {
            sender.sendMessage(MessageUtil.parse("<yellow>Usage: /kitadmin <reload|resetcooldown> [player] [kit]</yellow>"));
            return true;
        }

        if (args[0].equalsIgnoreCase("reload")) {
            plugin.reloadPlugin();
            sender.sendMessage(MessageUtil.parse(plugin.getConfig().getString("messages.reloaded")));
            return true;
        }

        if (args[0].equalsIgnoreCase("resetcooldown") && args.length >= 3) {
            OfflinePlayer target = Bukkit.getOfflinePlayer(args[1]);
            String kitId = args[2];
            plugin.getCooldownManager().resetCooldown(target.getUniqueId(), kitId);
            sender.sendMessage(MessageUtil.parse("<green>Reset cooldown for " + target.getName() + " on kit " + kitId + ".</green>"));
            return true;
        }

        sender.sendMessage(MessageUtil.parse("<red>Invalid syntax. Use: /kitadmin <reload|resetcooldown></red>"));
        return true;
    }

    @Override
    public @Nullable List<String> onTabComplete(@NotNull CommandSender sender, @NotNull Command command, @NotNull String label, @NotNull String[] args) {
        if (args.length == 1) {
            return Arrays.asList("reload", "resetcooldown");
        }
        return null;
    }
}
`;

  const playerDataStorageJava = `package ${packageName}.storage;

import ${packageName}.KitPlugin;
import org.bukkit.configuration.file.YamlConfiguration;

import java.io.File;
import java.io.IOException;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Thread-safe Player Data storage using asynchronous writes to avoid server tick stalls.
 */
public class PlayerDataStorage {

    private final KitPlugin plugin;
    private final File dataFolder;
    private final Map<UUID, YamlConfiguration> cache = new ConcurrentHashMap<>();

    public PlayerDataStorage(KitPlugin plugin, File dataFolder) {
        this.plugin = plugin;
        this.dataFolder = dataFolder;
    }

    private File getFile(UUID uuid) {
        return new File(dataFolder, uuid.toString() + ".yml");
    }

    public synchronized YamlConfiguration getPlayerData(UUID uuid) {
        return cache.computeIfAbsent(uuid, id -> {
            File f = getFile(id);
            if (f.exists()) {
                return YamlConfiguration.loadConfiguration(f);
            }
            return new YamlConfiguration();
        });
    }

    public long getLastClaimTime(UUID uuid, String kitId) {
        YamlConfiguration config = getPlayerData(uuid);
        return config.getLong("cooldowns." + kitId.toLowerCase(), 0L);
    }

    public void setLastClaimTime(UUID uuid, String kitId, long timestamp) {
        YamlConfiguration config = getPlayerData(uuid);
        config.set("cooldowns." + kitId.toLowerCase(), timestamp);
        saveAsync(uuid);
    }

    public void saveAsync(UUID uuid) {
        plugin.getServer().getScheduler().runTaskAsynchronously(plugin, () -> {
            YamlConfiguration config = cache.get(uuid);
            if (config != null) {
                try {
                    config.save(getFile(uuid));
                } catch (IOException e) {
                    plugin.getLogger().warning("Failed to save data for " + uuid + ": " + e.getMessage());
                }
            }
        });
    }

    public void saveAllSync() {
        for (Map.Entry<UUID, YamlConfiguration> entry : cache.entrySet()) {
            try {
                entry.getValue().save(getFile(entry.getKey()));
            } catch (IOException e) {
                plugin.getLogger().warning("Failed to save data for " + entry.getKey());
            }
        }
    }
}
`;

